pub(crate) fn pg_number_consumed(n: &Number) -> i64 {
    match n {
        Number::Not => -1,
        Number::Refused { consumed, .. } => { let consumed = *consumed; consumed },
        Number::Taken { consumed, .. } => { let consumed = *consumed; consumed },
    }
}

