pub fn pg_render(source: &str) -> String {
    let input = Bytes(source.bytes().collect::<Vec<_>>());
    let ts = match nikaia_std::grammar::parse_bytes(&*input, ParserGrammarOverBytes::parse_tokens()) {
        Ok(value) => value,
        Err(error) => { return format!("refused: {}", error); },
    };
    let mut parts: Vec<String> = Vec::new();
    for t in ts.iter() {
        let b = if t.broke { "\\n" } else { "" };
        parts.push(format!("{}{}@{}", b, pg_kind_text(&t.kind), t.start));
    }
    parts.join(" | ")
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn pg_count(source: &str) -> String {
    let input = Bytes(source.bytes().collect::<Vec<_>>());
    let ts = match nikaia_std::grammar::parse_bytes(&*input, ParserGrammarOverBytes::parse_tokens()) {
        Ok(value) => value,
        Err(error) => { return format!("refused: {}", error); },
    };
    let mut words = 0;
    let mut names = 0;
    let mut docs = 0;
    let mut literals = 0;
    let mut other = 0;
    let mut breaks = 0;
    for t in ts.iter() {
        if t.broke { breaks += 1; }
        match &t.kind {
            PgKind::Keyword(_) => { words += 1; },
            PgKind::Reserved(_) => { words += 1; },
            PgKind::Name(_) => { names += 1; },
            PgKind::Underscore => { names += 1; },
            PgKind::Doc(_) => { docs += 1; },
            PgKind::Str(_) => { literals += 1; },
            PgKind::Char(_) => { literals += 1; },
            PgKind::Digits(_) => { literals += 1; },
            PgKind::Other(_) => { other += 1; },
        }
    }
    format!("{} words, {} names, {} docs, {} literals, {} other, {} after a line break", words, names, docs, literals, other, breaks)
}

pub(crate) fn pg_kind_text(kind: &PgKind) -> String {
    match kind {
        PgKind::Keyword(w) => format!("kw {}", w),
        PgKind::Reserved(w) => format!("res {}", w),
        PgKind::Name(w) => format!("name {}", w),
        PgKind::Underscore => String::from("_"),
        PgKind::Str(t) => format!("str {}", t),
        PgKind::Char(t) => format!("char {}", t),
        PgKind::Digits(t) => format!("digits {}", t),
        PgKind::Doc(d) => format!("doc {}", d.replace("\n", "\\n")),
        PgKind::Other(c) => format!("other {}", c),
    }
}

